<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#ffc928"><link rel="manifest" href="manifest.json"><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/responsive.css"><link rel="apple-touch-icon" href="assets/icons/icon-192.svg"><title>Profile</title></head><body><main class="app"><div id="top"></div><div class="summary"><h2>Hello, Food Lover 👋</h2><p class="desc">Manage your app experience and installation.</p></div><div class="install"><span>📲 <b>Install Foodie</b><br><small>Add the app to your home screen</small></span><button onclick="installApp()">Install App</button></div><div class="summary"><p><span>Saved favorites</span><b id="fc"></b></p><p><span>Cart items</span><b id="cc"></b></p><p><span>Offline ready</span><b>Yes</b></p></div><div id="nav"></div></main><div class="toast"></div><div class="sheet" onclick="if(event.target===this)this.classList.remove('show')"><div><h2>Install this app on your iPhone</h2><p>1. Tap the Share button in Safari.<br><br>2. Select <b>Add to Home Screen</b>.<br><br>3. Tap <b>Add</b>.</p><button class="primary" onclick="this.closest('.sheet').classList.remove('show')">Got it</button></div></div><script src="js/products.js"></script><script src="js/app.js"></script><script src="js/cart.js"></script><script src="js/pwa.js"></script><script>$('#top').innerHTML=top('Profile',true);$('#nav').innerHTML=nav('profile');$('#fc').textContent=favorites().length;$('#cc').textContent=cartCount();renderBadges();</script></body></html>